import datetime
import unittest

from clock import from_epoch


class TestClock(unittest.TestCase):
    def test_epoch(self):
        self.assertEqual(from_epoch(0), datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc))
        self.assertEqual(from_epoch(86400), datetime.datetime(1970, 1, 2, tzinfo=datetime.timezone.utc))


if __name__ == '__main__':
    unittest.main()
